import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BfWdyVj4.js";const g=JSON.parse('{"title":"Screensaver","description":"","frontmatter":{},"headers":[],"relativePath":"features/screensaver.md","filePath":"features/screensaver.md","lastUpdated":1795733687000}'),r={name:"features/screensaver.md"};function n(i,e,d,h,c,l){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="screensaver" tabindex="-1">Screensaver <a class="header-anchor" href="#screensaver" aria-label="Permalink to &quot;Screensaver&quot;">​</a></h1><p>When nobody has touched a display for a few minutes, Frog Hub can show a screensaver instead of its usual screen:</p><ul><li><strong>A big clock</strong> with the date;</li><li><strong>the personality&#39;s face</strong>, floating about;</li><li><strong>photos</strong>, a slideshow (see below);</li><li><strong>a mix</strong>, two minutes of each in turn.</li></ul><p>The clock and the face drift slowly round the screen, so nothing stays lit in the same place for hours (old screens can burn in). A tap anywhere wakes it up, and that tap only wakes it: it never presses whatever is underneath.</p><p>It stays away while someone is talking to the assistant, an alarm is ringing, Settings or the keyboard are open, or a card is full screen, and goes as soon as the wake word is heard or a message arrives. During night mode it&#39;s dimmed like everything else.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Under <strong>Settings → Screensaver</strong>, shared by every display like the look and night mode (a grown-up&#39;s Save in admin mode updates them all):</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Screensaver when nobody&#39;s using it</td><td>The switch. Off to begin with</td></tr><tr><td>Show</td><td>A big clock, the face, photos, or a mix</td></tr><tr><td>After … idle minutes</td><td>How long nobody has touched it first (5 to begin with)</td></tr><tr><td>Dim the screen while it&#39;s on</td><td>Turns the screen down, and back up when it wakes</td></tr><tr><td>Only at certain times</td><td>From and to (say 07:00 to 21:00; it can go over midnight). Outside them, no screensaver</td></tr></tbody></table><p>In a browser there&#39;s no way to turn the screen itself down, so &quot;dim&quot; darkens the picture instead.</p><h2 id="in-the-android-app" tabindex="-1">In the Android app <a class="header-anchor" href="#in-the-android-app" aria-label="Permalink to &quot;In the Android app&quot;">​</a></h2><p><a href="/developers/android">The display app</a> keeps its own screensaver settings, in its corner menu (tap the top-left corner five times) and under <strong>Settings → Screensaver</strong> on that tablet, and Frog Hub uses those instead of the shared ones. There, dimming turns the tablet&#39;s backlight down. The app&#39;s own screen-off comes after the screensaver: if the screensaver is set to start at the same time or later, it starts a minute before the screen goes off instead (the corner menu says so). Older versions of the app fall back to the shared settings.</p><h2 id="photos" tabindex="-1">Photos <a class="header-anchor" href="#photos" aria-label="Permalink to &quot;Photos&quot;">​</a></h2><p>The slideshow shows, in a shuffled order, a new picture every 15 seconds from:</p><ul><li><strong>the server&#39;s photo folder</strong>, <code>~/.config/froghub/photos</code> (or <code>photosDir</code> in <code>instance.json</code>): <code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, <code>.gif</code> and <code>.webp</code> files. Old tablets have little memory, so keep them about screen-sized;</li><li><strong>a list of picture addresses</strong>, which a grown-up types in under <strong>Settings → Screensaver</strong> in admin mode (one per line, <code>http://</code> or <code>https://</code>).</li></ul><p>With no photos at all, the slideshow shows the clock.</p>',15)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
